from common import add, case
# Niveau 1 : types, références, conteneurs et objets.
add(1,'references','reference_alias',lambda n:case(f'int x={n};int& r=x;r+=3;std::cout<<x;',n+3,'Une référence lvalue est un alias de l’objet initial ; son affectation agit sur cet objet.','r est un alias de x|L’écriture via r modifie x|La référence doit être initialisée','r est une copie indépendante|Une référence se réassocie par affectation|r doit être supprimée avec delete'))
add(1,'functions','value_parameter',lambda n:case(f'int x={n};bump(x);std::cout<<x;',n,'Le paramètre par valeur est un objet distinct ; son incrément ne modifie pas l’argument.','Le paramètre est copié|La variable de main reste inchangée|Le passage ne nécessite aucun pointeur','L’argument est passé implicitement par référence|La fonction modifie toujours x|Le retour void réaffecte l’argument',preamble='void bump(int x){++x;}'))
add(1,'functions','reference_parameter',lambda n:case(f'int x={n};bump(x);std::cout<<x;',n+1,'int& lie le paramètre à l’objet de l’appelant.','Le paramètre est une référence|La variable de main est modifiée|Aucun retour de valeur n’est nécessaire pour cet effet','Le paramètre est une copie|Le type int& désigne un pointeur nul|L’appel exige un opérateur & explicite',preamble='void bump(int& x){++x;}'))
add(1,'const','const_reference',lambda n:case(f'int x={n};const int& r=x;x+=2;std::cout<<r;',n+2,'const qualifie l’accès via r, pas l’objet x qui demeure modifiable par son nom.','r observe le même objet x|x n’est pas déclaré const|L’écriture via r serait interdite','r fige définitivement x|r contient une copie|Modifier x invalide automatiquement r'))
add(1,'variables','auto_deduction',lambda n:case(f'int x={n};auto y=x;y+=2;std::cout<<x<<" "<<y;',f'{n} {n+2}','auto déduit ici int, pas int& : y est une copie distincte.','y a le type int|y possède son propre stockage|Modifier y ne modifie pas x','auto crée toujours une référence|y a le type int*|y est const automatiquement',wrong=[f'{n+2} {n+2}','Erreur de compilation',f'{n} {n}']))
add(1,'vector','vector_push_size',lambda n:case(f'std::vector<int> v{{{n},2}};v.push_back(7);std::cout<<v.size()<<" "<<v.back();','3 7','push_back ajoute un élément ; back accède au dernier élément, sans retirer celui-ci.','size compte les éléments|back ne retire pas l’élément|Le conteneur peut réallouer','La capacité vaut forcément la taille|back retire le dernier élément|vector impose une longueur fixe',wrong=['2 7','3 2','Erreur de compilation']))
add(1,'vector','reserve_not_resize',lambda n:case(f'std::vector<int> v;v.reserve({n+8});std::cout<<v.size();',0,'reserve prépare une capacité sans construire des éléments ; resize modifierait la taille.','La capacité est au moins celle demandée|La taille reste nulle|L’accès par v[0] ne serait pas valide','reserve construit tous les éléments|La capacité est forcément exactement celle demandée|reserve équivaut à resize'))
add(1,'collections','array_size',lambda n:case(f'std::array<int,4> a{{{n},2}};std::cout<<a.size()<<" "<<a[3];','4 0','std::array a une taille fixe ; l’initialisation partielle initialise les int restants à zéro.','La taille fait partie du type|Le quatrième élément est initialisé à zéro|std::array ne se redimensionne pas','La taille vaut deux|Le dernier élément est indéterminé|push_back est disponible sur std::array',wrong=['2 0',f'4 {n}','Erreur de compilation']))
add(1,'strings','string_append',lambda n:case(f'std::string s="ab{n}";s+="!";std::cout<<s.size();',4,'std::string possède une séquence de caractères modifiable ; += ajoute à la fin.','s possède son contenu|L’ajout augmente size|Le terminateur ne fait pas partie de size','size compte le terminateur nul|Le littéral d’origine est modifié|La chaîne doit être libérée avec free'))
add(1,'strings','string_at_bounds',lambda n:case(f'std::string s="x{n}";try{{std::cout<<s.at(8);}}catch(const std::out_of_range&){{std::cout<<"caught";}}','caught','at vérifie les bornes et lève out_of_range ; le bloc catch intercepte cette exception.','L’indice dépasse size|at vérifie les bornes|L’exception est interceptée','at ajoute des caractères|Le comportement est indéfini malgré le catch|at retourne un caractère nul hors limites',wrong=['Caractère nul','Comportement indéfini','Erreur de compilation']))
add(1,'loops','range_copy',lambda n:case(f'std::vector<int> v{{{n},2}};for(auto x:v)x+=3;std::cout<<v[0];',n,'auto x copie chaque élément ; il faudrait auto& x pour modifier les éléments.','x est une copie|Le vector reste inchangé|Le type des éléments est int','x est automatiquement une référence|La boucle déplace le vector|L’affectation modifie le conteneur'))
add(1,'loops','range_reference',lambda n:case(f'std::vector<int> v{{{n},2}};for(auto& x:v)x+=3;std::cout<<v[0];',n+3,'auto& lie x à chaque élément ; les écritures modifient le vector.','x est une référence|Les éléments sont modifiés|Le conteneur conserve sa taille','La boucle copie chaque élément|La taille augmente à chaque passage|La référence doit être supprimée'))
add(1,'classes','constructor_initialization',lambda n:case(f'P p({n});std::cout<<p.x;',n+2,'La liste d’initialisation construit le membre avec l’expression fournie.','x est initialisé avant le corps du constructeur|p est un objet automatique|Le constructeur reçoit son argument par valeur','x est initialisé après le corps|La liste modifie une variable globale|new est obligatoire pour construire P',preamble='struct P{int x;explicit P(int v):x(v+2){}};'))
add(1,'classes','default_member_initializer',lambda n:case(f'P p;std::cout<<p.x;',n+4,'L’initialiseur de membre fournit la valeur quand le constructeur ne la remplace pas.','Le membre possède un initialiseur|p est créé sans argument|Aucune allocation explicite n’est nécessaire','Tout int membre vaut toujours zéro|Le code lit un int non initialisé|L’initialiseur exige un objet static',preamble=f'struct P{{int x={n+4};}};'))
add(1,'enum','scoped_enum',lambda n:case(f'Color c=Color::red;int x=c;std::cout<<x;','Erreur de compilation','Une enum class ne se convertit pas implicitement en int ; static_cast<int> expliciterait la conversion.','Color est une enum scoped|L’énumérateur est qualifié|La conversion implicite vers int est interdite','Une enum class se convertit toujours en int|Le code échoue seulement à l’exécution|Les énumérateurs de Color sont des macros',preamble=f'enum class Color{{red={n},blue}};',mode='compile_fail'))
add(1,'control_flow','ternary_branch',lambda n:case(f'int x={n};std::cout<<(x%2==0?"even":"odd");','even' if n%2==0 else 'odd','L’opérateur conditionnel n’évalue que la branche correspondant au test.','Le test utilise le reste entier|Une seule branche est évaluée|Les deux résultats sont des littéraux de chaîne','Les deux branches sont affichées|Le test est un ET bit à bit|Le résultat dépend de l’adresse des littéraux',wrong=['even' if n%2 else 'odd','evenodd','Erreur de compilation']))
add(1,'memory','unique_ptr_scope',lambda n:case(f'auto p=std::make_unique<int>({n});*p+=2;std::cout<<*p;',n+2,'unique_ptr possède exclusivement l’objet et le détruit automatiquement à sa propre destruction.','Le pointeur intelligent possède l’int|Le déréférencement modifie l’int|La libération est automatique','Un free explicite est requis|unique_ptr est copiable|Le pointeur peut être déréférencé après destruction'))
add(1,'algorithms','find_iterator',lambda n:case(f'std::vector<int> v{{1,{n+2},9}};auto it=std::find(v.begin(),v.end(),{n+2});std::cout<<(it!=v.end());',1,'find retourne le premier itérateur correspondant ou end si aucun élément ne convient.','L’élément recherché existe|end est la sentinelle de fin|find ne modifie pas le vector','find renvoie toujours un indice entier|end désigne le dernier élément|find trie les éléments'))
add(1,'functions','default_argument',lambda n:case(f'std::cout<<add({n});',n+5,'L’argument par défaut est utilisé quand cet argument est omis au site d’appel.','Le deuxième argument est omis|La valeur par défaut complète l’appel|Le retour est un int','Les deux arguments sont obligatoires|Le défaut modifie une variable globale|La valeur par défaut remplace aussi les arguments explicitement fournis',preamble='int add(int x,int y=5){return x+y;}'))
add(1,'collections','map_insert_index',lambda n:case(f'std::map<int,int> m;int x=m[{n}];std::cout<<m.size()<<" "<<x;','1 0','operator[] insère une clé absente et initialise son int à zéro ; at n’insérerait pas.','La clé était absente|L’accès insère un élément|L’int est initialisé à zéro','operator[] ne modifie jamais une map|L’int lu est indéterminé|std::map utilise des indices contigus',wrong=['0 0','1 1','Exception non interceptée']))

# Niveau 2 : règles de déduction, invalidation et propriété.
add(2,'references','auto_reference',lambda n:case(f'int x={n};auto& y=x;y+=4;std::cout<<x;',n+4,'auto& préserve le caractère référence ; y est un alias et non une copie.','Le type de y est int&|y désigne x|L’écriture ne change pas l’adresse liée','Le type de y est int|auto& interdit les modifications|Une affectation réassocie y à un autre objet'))
add(2,'const','auto_drops_top_const',lambda n:case(f'const int x={n};auto y=x;y++;std::cout<<y;',n+1,'La déduction par valeur avec auto retire le const de premier niveau ; x reste const.','y est modifiable|x reste const|y est une copie','y est une référence constante|L’écriture modifie x|Le const de x est retiré'))
add(2,'references','decltype_parentheses',lambda n:case(f'int x={n};decltype((x)) y=x;y+=2;std::cout<<x;',n+2,'decltype((x)) observe une expression lvalue et produit int&, contrairement à decltype(x).','Les parenthèses changent la règle de decltype|y est une référence|x est modifié via y','decltype((x)) produit toujours int|y est une référence rvalue|decltype évalue x à l’exécution'))
add(2,'functions','overload_resolution',lambda n:case(f'std::cout<<f({n})<<f({n}.5);','ID','Le premier littéral correspond exactement à int, le second à double.','Les appels choisissent deux surcharges|Les correspondances exactes sont favorisées|Le type de retour ne suffit pas à distinguer des surcharges','Le premier appel choisit toujours double|Le choix est fait à l’exécution|Les deux appels sont ambigus',preamble="char f(int){return 'I';}char f(double){return 'D';}",wrong=['II','DD','Erreur de compilation']))
add(2,'classes','explicit_constructor',lambda n:case(f'P p={n};','Erreur de compilation','La copie-initialisation depuis int ne peut pas utiliser ce constructeur explicit ; P p(n) serait valide.','Le constructeur est explicit|La copie-initialisation est utilisée|Une initialisation directe permettrait l’appel','explicit interdit toute construction|La conversion est reportée à l’exécution|Le membre doit être public pour que l’appel soit implicite',preamble='struct P{explicit P(int){}};',mode='compile_fail'))
add(2,'memory','unique_ptr_move',lambda n:case(f'auto a=std::make_unique<int>({n});auto b=std::move(a);std::cout<<(a==nullptr)<<" "<<*b;',f'1 {n}','Le déplacement transfère la propriété exclusive et laisse le unique_ptr source vide.','b possède l’int|a est vide après ce déplacement|L’objet alloué n’est pas copié','Les deux pointeurs restent propriétaires|std::move effectue une copie profonde|a conserve nécessairement son ancienne adresse',wrong=[f'0 {n}','Erreur de compilation',f'1 {n+1}']))
add(2,'memory','shared_ptr_count',lambda n:case(f'auto a=std::make_shared<int>({n});{{auto b=a;}}std::cout<<a.use_count();',1,'La copie augmente le nombre de propriétaires forts ; la fin du bloc détruit b et le rediminue.','La copie partage l’allocation|b est détruit à la fin du bloc|a reste propriétaire','La copie duplique l’int dans une allocation indépendante|b doit être supprimé manuellement|La destruction de b détruit forcément l’int'))
add(2,'vector','iterator_reallocation',lambda n:case(f'std::vector<int> v{{{n}}};int *p=v.data();v.reserve(v.capacity()+1);std::cout<<*p;','Comportement indéfini','Demander une capacité supérieure à l’actuelle force une réallocation ; les pointeurs vers les anciens éléments sont invalidés.','reserve force ici une réallocation|p est invalidé|Un nouvel appel à data serait nécessaire','p suit automatiquement le nouveau stockage|reserve ne peut jamais réallouer|L’ancienne adresse reste utilisable si la valeur est la même',wrong=[str(n),'Erreur de compilation','Segfault garanti'],mode='analysis'))
add(2,'vector','erase_iterator',lambda n:case(f'std::vector<int> v{{{n},2,3}};auto it=v.erase(v.begin());std::cout<<*it;',2,'erase renvoie un itérateur vers l’élément suivant celui supprimé. Utiliser l’ancien begin après erase ne serait pas la bonne stratégie.','Le premier élément est supprimé|L’itérateur retourné vise le suivant|La taille devient deux','erase renvoie toujours end|Le vector garde trois éléments|Le premier élément reste accessible via son ancien itérateur'))
add(2,'strings','string_view_alias',lambda n:case(f'std::string s="ab{n}";std::string_view v=s;s[0]=\'X\';std::cout<<v;',f'Xb{n}','string_view ne possède pas le contenu ; modifier un caractère sans réallocation est visible via la vue.','La vue emprunte le stockage|La taille de s ne change pas|Aucune réallocation n’est provoquée par cette écriture','La vue contient une copie indépendante|string_view libère s à sa destruction|La vue interdit toute modification via le propriétaire',wrong=[f'ab{n}','Erreur de compilation','Comportement indéfini']))
add(2,'classes','virtual_dispatch',lambda n:case(f'D d;B& b=d;std::cout<<b.f();',n+1,'L’appel d’une fonction virtuelle via une référence de base atteint la redéfinition du type dynamique.','b est une référence de base|L’objet dynamique est D|La fonction est virtuelle','La référence provoque un slicing|Le type statique impose B::f|virtual oblige une allocation avec new',preamble=f'struct B{{virtual int f()const{{return {n};}}virtual ~B()=default;}};struct D:B{{int f()const override{{return {n+1};}}}};'))
add(2,'classes','object_slicing',lambda n:case(f'D d;B b=d;std::cout<<b.f();',n,'Construire un objet B par valeur à partir de D copie seulement la partie B : le nouvel objet a le type dynamique B.','b est un objet distinct de type B|Le slicing a lieu par copie vers la base|Une référence de base éviterait cette copie','b reste dynamiquement un D|virtual prévient toutes les formes de slicing|La copie est toujours une erreur de compilation',preamble=f'struct B{{virtual int f()const{{return {n};}}virtual ~B()=default;}};struct D:B{{int f()const override{{return {n+1};}}}};'))
add(2,'functions','lambda_value_capture',lambda n:case(f'int x={n};auto f=[x]{{return x;}};x+=4;std::cout<<f();',n,'La capture par valeur conserve une copie de x au moment de la création de la fermeture.','La capture est une copie|La réaffectation extérieure ne modifie pas la capture|L’appel n’a pas besoin de mutable','La capture suit toujours la variable extérieure|[x] équivaut à [&x]|La fermeture renvoie une référence vers x'))
add(2,'functions','lambda_reference_capture',lambda n:case(f'int x={n};auto f=[&x]{{return x;}};x+=4;std::cout<<f();',n+4,'La capture par référence observe la variable extérieure, encore vivante pendant l’appel.','La capture est une référence|x vit pendant l’appel|La modification extérieure est observée','La capture copie x|L’objet x est détruit à la création de f|Toute capture par référence exige mutable'))
add(2,'enum','optional_value_or',lambda n:case(f'std::optional<int> x;std::cout<<x.value_or({n+5});',n+5,'Un optional vide ne contient pas d’int ; value_or fournit une valeur de secours sans lever bad_optional_access.','x est vide|Le secours est utilisé|value_or ne rend pas x engagé','x contient implicitement zéro|value_or stocke le secours dans x|Le code lève forcément une exception'))
add(2,'generics','template_deduction_conflict',lambda n:case(f'auto x=pick({n},2.5);(void)x;','Erreur de compilation','Le même paramètre T serait déduit int et double. Cette déduction ne cherche pas un type commun via des conversions.','Deux déductions de T entrent en conflit|Les arguments ont des types différents|Un T explicite compatible changerait l’analyse','La déduction choisit toujours double|Les types de retour déterminent seuls T|L’erreur n’arrive qu’à l’édition de liens',preamble='template<class T>T pick(T a,T b){return a<b?a:b;}',mode='compile_fail'))
add(2,'collections','structured_binding_copy',lambda n:case(f'std::pair<int,int> p{{{n},2}};auto [a,b]=p;a+=3;std::cout<<p.first;',n,'Une décomposition par auto sans référence possède une copie du pair ; modifier a ne touche pas p.','La décomposition est par valeur|p reste inchangé|auto& aurait permis de modifier p','La décomposition crée toujours des références vers p|p est déplacé et inutilisable|Les types doivent être différents'))
add(2,'algorithms','remove_erase_idiom',lambda n:case(f'std::vector<int> v{{{n},0,0,7}};auto e=std::remove(v.begin(),v.end(),0);std::cout<<v.size()<<" "<<std::distance(v.begin(),e);','4 2','remove réorganise la plage et renvoie la nouvelle fin logique ; il ne modifie pas size du vector.','Deux éléments sont conservés logiquement|size reste quatre avant erase|Les éléments après e ne constituent plus la plage utile','remove appelle automatiquement erase|size vaut deux|Les éléments après e sont forcément tous nuls',wrong=['2 2','4 4','Erreur de compilation']))
add(2,'memory','new_array_delete',lambda n:case(f'int *p=new int[{n+2}]{{}};std::cout<<p[0];delete[] p;',0,'{} initialise les éléments int à zéro ; une allocation new[] doit être libérée avec delete[].','Les int sont initialisés à zéro|delete[] correspond à new[]|p ne doit plus être déréférencé après delete[]','delete sans crochets serait interchangeable|free est la libération correspondante|Les éléments sont indéterminés'))
add(2,'const','const_member_function',lambda n:case(f'const P p({n});std::cout<<p.get();',n,'Une méthode const peut être appelée sur un objet const et ne modifie pas ici les membres ordinaires.','get est qualifiée const|L’objet p est const|La lecture du membre est permise','Une méthode non const serait toujours appelable ici|const impose un objet static|const fait une copie de l’objet à chaque appel',preamble='struct P{int x;explicit P(int v):x(v){}int get()const{return x;}};'))

# Niveau 3 : durées de vie, génériques, exceptions et modèle mémoire.
add(3,'classes','virtual_destructor',lambda n:case(f'B *p=new D;delete p;','Comportement indéfini','Supprimer un objet dérivé via un pointeur de base exige ici un destructeur virtuel dans la base.','Le type dynamique est D|La suppression se fait via B*|Un destructeur virtuel de base corrigerait le contrat','Un destructeur public suffit|Le compilateur doit refuser delete p|Le destructeur dérivé est forcément appelé',preamble=f'struct B{{int x={n};~B()=default;}};struct D:B{{std::string s="resource";}};',wrong=['Destruction complète garantie','Erreur de syntaxe obligatoire','Fuite garantie sans autre conséquence'],mode='analysis'))
add(3,'references','dangling_string_view',lambda n:case('std::string_view v=bad();std::cout<<v;','Vue pendante : comportement indéfini à la lecture','La string locale est détruite au retour. string_view ne possède pas les caractères et ne prolonge pas leur durée de vie.','La vue n’est pas propriétaire|La string locale est détruite|Retourner std::string serait un contrat possédant','string_view clone la chaîne|La conversion prolonge toujours la durée de vie|Le compilateur doit refuser le retour',preamble=f'std::string_view bad(){{std::string s="data{n}";return s;}}',wrong=[f'data{n}','Erreur de compilation obligatoire','Chaîne vide garantie'],mode='analysis'))
add(3,'references','temporary_lifetime',lambda n:case(f'const std::string& r=std::string("a{n}");std::cout<<r.size();',2,'La liaison directe de cette référence locale const prolonge la durée de vie du temporaire jusqu’à celle de la référence.','La référence est directement liée au temporaire|Le temporaire vit jusqu’à la fin de la portée de r|Aucune copie possédée par r n’est créée','Toute référence à un temporaire pend immédiatement|La durée est prolongée par n’importe quel retour de fonction|Le temporaire est nécessairement alloué par new',wrong=['Comportement indéfini','Erreur de compilation','0']))
add(3,'references','forwarding_reference',lambda n:case(f'int x={n};std::cout<<kind(x)<<kind({n+1});','LR','Avec T déduit, T&& est une référence de transfert. L’effondrement des références conserve la catégorie de l’argument pour ce test.','Le premier T est déduit comme référence lvalue|Le second argument est une prvalue|La déduction dépend de la catégorie de valeur','T&& est toujours une référence rvalue simple|Les deux appels déduisent T comme int&|Le premier appel déplace x',preamble="template<class T>char kind(T&&){return std::is_lvalue_reference<T>::value?'L':'R';}",wrong=['LL','RR','Erreur de compilation']))
add(3,'memory','move_cast_not_action',lambda n:case(f'auto p=std::make_unique<int>({n});std::move(p);std::cout<<(p!=nullptr);',1,'std::move est un cast vers une xvalue. Sans opération qui consomme cette expression, aucune propriété n’est transférée.','L’expression retournée est inutilisée|p reste propriétaire|Le transfert exige une opération de déplacement effective','std::move détruit immédiatement l’objet|p devient toujours nul au seul appel de std::move|Le pointeur alloué est cloné'))
add(3,'memory','weak_ptr_expired',lambda n:case(f'std::weak_ptr<int> w;{{auto p=std::make_shared<int>({n});w=p;}}std::cout<<w.expired();',1,'weak_ptr n’ajoute pas de propriétaire fort ; l’objet est détruit quand le dernier shared_ptr disparaît.','w ne maintient pas l’int en vie|Le dernier propriétaire fort sort de portée|lock pourrait retourner un shared_ptr vide','weak_ptr empêche la destruction de l’objet|expired détruit lui-même l’int|lock garantit toujours une valeur'))
add(3,'classes','initialization_order',lambda n:case(f'P p({n});std::cout<<p.a<<" "<<p.b;',f'{n} {n+2}','Les membres sont initialisés dans leur ordre de déclaration, pas dans l’ordre écrit dans la liste d’initialisation.','a est déclaré avant b|a est initialisé avant b|Le calcul de b peut utiliser a déjà initialisé','b est initialisé en premier|La liste d’initialisation choisit l’ordre des membres|L’ordre dépend de l’optimisation',preamble='struct P{int a;int b;explicit P(int v):b(a+2),a(v){}};',wrong=['Valeurs indéterminées','Erreur de compilation',f'{n+2} {n}']))
add(3,'exceptions','raii_unwind',lambda n:case(f'try{{Log x({n});throw 7;}}catch(int){{std::cout<<"C";}}',f'D{n}C','La propagation de l’exception détruit les objets automatiques construits avant de transférer le contrôle au catch correspondant.','Le destructeur est exécuté pendant le déroulement|Le catch correspond à int|La ressource automatique est nettoyée','throw saute toujours les destructeurs|Le catch s’exécute avant le destructeur local|Une exception impose une fuite',preamble='struct Log{int x;explicit Log(int v):x(v){}~Log(){std::cout<<"D"<<x;}};',wrong=[f'CD{n}','C','Erreur de compilation']))
add(3,'exceptions','noexcept_throw',lambda n:case(f'try{{f({n});}}catch(...){{std::cout<<"caught";}}','Appel de std::terminate','Une exception qui s’échappe d’une fonction noexcept appelle terminate ; le catch de l’appelant ne l’intercepte pas.','f est déclarée noexcept|Une exception quitte f|Le catch extérieur ne récupère pas cette exception','noexcept interdit syntaxiquement tout throw|Le catch extérieur affiche forcément caught|Le programme continue normalement après f',preamble='void f(int x)noexcept{throw x;}',wrong=['caught','Erreur de compilation obligatoire','Aucune sortie et retour normal'],mode='analysis'))
add(3,'generics','if_constexpr',lambda n:case(f'std::cout<<size_of({n});',1,'if constexpr écarte la branche non retenue lors de l’instanciation ; la branche dépendante x.size() n’a pas à être valide pour int.','La condition est connue à la compilation|T est int pour cet appel|La branche dépendante non retenue est écartée','Les deux branches sont exécutées|La branche x.size() rend tout appel invalide|if constexpr impose un objet const',preamble='template<class T>int size_of(const T& x){if constexpr(std::is_integral_v<T>)return 1;else return static_cast<int>(x.size());}'))
add(3,'generics','fold_expression',lambda n:case(f'std::cout<<sum({n},2,3);',n+5,'L’expression de repli applique + sur le paquet de paramètres ; le zéro initialise le repli et permet un paquet vide.','Le paquet contient trois arguments|Le repli utilise +|Le zéro donne aussi un résultat pour un paquet vide','Le paquet doit contenir exactement deux arguments|Le repli exige une récursion manuelle|Le repli est une boucle de préprocesseur',preamble='template<class...T>auto sum(T...x){return (0+...+x);}'))
add(3,'const','mutable_cache',lambda n:case(f'const Cache c;std::cout<<c.get()<<" "<<c.get();',f'{n+1} {n+2}','Un membre mutable peut être modifié dans une méthode const. const n’implique pas automatiquement une sûreté entre threads.','Le membre est déclaré mutable|get est une méthode const|Aucune synchronisation entre threads n’est fournie ici','Toute écriture dans une méthode const est interdite|mutable rend l’incrément atomique|const empêche toute variation du retour',preamble=f'struct Cache{{mutable int count={n};int get()const{{return ++count;}}}};',wrong=['Erreur de compilation',f'{n+1} {n+1}','Comportement indéfini']))
add(3,'concurrency','atomic_fetch',lambda n:case(f'std::atomic<int> x{{{n}}};int old=x.fetch_add(2,std::memory_order_relaxed);std::cout<<old<<" "<<x.load();',f'{n} {n+2}','fetch_add est une opération atomique qui renvoie l’ancienne valeur ; relaxed ne synchronise pas les autres objets à lui seul.','L’addition est atomique|Le retour est l’ancienne valeur|relaxed ne garantit pas un ordre inter-objets','relaxed supprime l’atomicité|Le retour est toujours la nouvelle valeur|Tout accès ordinaire devient ainsi protégé',wrong=[f'{n+2} {n+2}',f'{n} {n}','Erreur de compilation']))
add(3,'concurrency','mutex_guard',lambda n:case(f'int x={n};std::mutex m;{{std::lock_guard<std::mutex> g(m);x+=2;}}std::cout<<x;',n+2,'lock_guard verrouille à sa construction et déverrouille à sa destruction. Sa durée de vie définit la section protégée.','Le verrou est acquis à la construction|La fin du bloc libère le verrou|La modification est dans la portée du garde','Le garde est copiable|Le verrou reste détenu jusqu’à la fin du programme|Le mutex protège automatiquement les accès effectués hors du verrou'))
add(3,'algorithms','strict_weak_order',lambda n:case(f'std::vector<int> v{{{n},{n},2}};std::sort(v.begin(),v.end(),[](int a,int b){{return a<=b;}});','Le comparateur ne satisfait pas le contrat du tri','std::sort exige un ordre strict faible. a<=b est vrai pour a==b et viole l’irréflexivité.','Le comparateur est vrai sur des valeurs égales|L’irréflexivité est violée|Utiliser a<b fournit ici l’ordre usuel valide','Tout prédicat booléen suffit à sort|<= est un ordre strict|Le compilateur doit détecter cette violation',wrong=['Tri croissant garanti','Erreur de compilation obligatoire','Les doublons sont automatiquement supprimés'],mode='analysis'))
add(3,'collections','unordered_rehash',lambda n:case(f'std::unordered_map<int,int> m{{{{1,{n}}}}};int& r=m.at(1);m.rehash(m.bucket_count()*4);std::cout<<r;',n,'Un rehash invalide les itérateurs, mais pas les références ou pointeurs vers les éléments existants de ce conteneur.','La référence vise un élément existant|rehash ne supprime pas cet élément|Les itérateurs et références n’ont pas les mêmes garanties','Toutes les références sont invalidées par rehash|La valeur est réinitialisée à zéro|unordered_map stocke ses éléments comme un vector contigu'))
add(3,'generics','initializer_list_preference',lambda n:case(f'P p{{{n},2}};std::cout<<p.kind;','L','La sélection des constructeurs par accolades favorise un constructeur initializer_list viable.','La construction utilise des accolades|initializer_list<int> est viable|Les parenthèses auraient une autre résolution','Le constructeur à deux int est toujours préféré|Les accolades désactivent initializer_list|Le choix est aléatoire',preamble="struct P{char kind;P(int,int):kind('I'){}P(std::initializer_list<int>):kind('L'){}};",wrong=['I','Erreur de compilation','Deux constructeurs sont exécutés']))
add(3,'references','structured_binding_ref',lambda n:case(f'std::pair<int,int> p{{{n},2}};auto& [a,b]=p;a+=3;std::cout<<p.first;',n+3,'La décomposition est liée par référence au pair ; a désigne son premier membre.','La décomposition n’est pas une copie de p|a modifie le premier membre|p vit pendant toute l’utilisation','auto& déplace p|a est un int indépendant|Les références de décomposition sont forcément const'))
add(3,'ownership','move_const_unique',lambda n:case(f'const auto p=std::make_unique<int>({n});auto q=std::move(p);','Erreur de compilation','std::move conserve const. Le constructeur de déplacement de unique_ptr ne prend pas de const rvalue et sa copie est supprimée.','La source est const|std::move ne retire pas const|unique_ptr n’est pas copiable','std::move retire const|Un déplacement clone l’allocation|Le pointeur source devient forcément nul',mode='compile_fail'))
add(3,'classes','override_signature',lambda n:case('D d;(void)d;','Erreur de compilation','La fonction dérivée non const n’a pas la même signature que la virtuelle const ; override transforme cette erreur de contrat en diagnostic.','La méthode de base est const|La méthode dérivée ne l’est pas|override exige une redéfinition effective','Le const final est ignoré pour redéfinir|override effectue une conversion de signature|L’erreur survient seulement au premier appel',preamble=f'struct B{{virtual int f()const{{return {n};}}}};struct D:B{{int f()override{{return 2;}}}};',mode='compile_fail'))
